      break;
    case T_GRASS:
      g.fillStyle = (tx + ty) % 2 ? '#79b957' : '#74b453';
      g.fillRect(x, y, TILE, TILE);
      for (let k = 0; k < 14; k += 1) {
        g.fillStyle = rng.chance(0.5) ? '#8ccb63' : '#64a246';
        g.fillRect(x + rng.range(0, TILE), y + rng.range(0, TILE), 3, 3);
      }
      break;
    case T_PLAZA:
      g.fillStyle = '#e7d8bd';
      g.fillRect(x, y, TILE, TILE);
      g.fillStyle = '#dcc9a8';
      g.fillRect(x + 2, y + 2, 28, 28);
