    case T_SAND:
      g.fillStyle = '#f0d9a2';
      g.fillRect(x, y, TILE, TILE);
      for (let k = 0; k < 12; k += 1) {
        g.fillStyle = rng.chance(0.5) ? '#e6cb8d' : '#f7e6b8';
        g.fillRect(x + rng.range(0, TILE), y + rng.range(0, TILE), 2, 2);
