}

function drawRoof(ctx, cam, b, now) {
  const corners = [lift(cam, b.x, b.y, b.height), lift(cam, b.x + b.w, b.y, b.height), lift(cam, b.x + b.w, b.y + b.h, b.height), lift(cam, b.x, b.y + b.h, b.height)];
