  const s = 1 + b.height / (CAMERA_HEIGHT - b.height);
  const x = corners[0].x;
  const y = corners[0].y;
  const w = b.w * s;
  const h = b.h * s;
  if (b.kind === 'villa') {
    ctx.strokeStyle = 'rgba(120,50,30,0.5)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    if (w > h) { ctx.moveTo(x + 6, y + h / 2); ctx.lineTo(x + w - 6, y + h / 2); } else { ctx.moveTo(x + w / 2, y + 6); ctx.lineTo(x + w / 2, y + h - 6); }
